<?php
namespace Tests\Feature;
use App\Models\{Owner,User,Venue,GatewayAccount,CheckoutAttempt};
use App\Services\{VenueSettings,BookingEngine};
use App\Services\Payments\GatewayCredentials;
use Illuminate\Encryption\Encrypter;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http,Crypt};
use Illuminate\Support\Str;
use Tests\TestCase;
class GatewayRecoveryTest extends TestCase {
 use RefreshDatabase;
 private function owner():Owner{$u=User::factory()->create();return Owner::unguarded(fn()=>Owner::create(['user_id'=>$u->id,'name'=>'Dueño','email'=>$u->email,'password'=>'OwnerPassword12345','activated'=>true,'email_verified_at'=>now()]));}
 private function venue(Owner $o):Venue{return Venue::create(['owner_id'=>$o->user_id,'owner_account_id'=>$o->id,'name'=>'Jardín','slug'=>'jardin-'.Str::lower(Str::random(6)),'published'=>true,'settings'=>array_replace(VenueSettings::defaults(),['capacity'=>100,'open_hour'=>10,'close_hour'=>26,'prep_minutes'=>0,'clean_minutes'=>0,'included_hours'=>8,'weekday_price'=>150000,'weekend_price'=>150000,'holiday_price'=>150000,'extra_hour_price'=>0,'deposit_value'=>30])]);}
 private function credentials(string $provider='paypal'):array{return match($provider){'paypal'=>['client_id'=>'test-client','client_secret'=>'test-private','merchant_id'=>'ABC23456789DE','webhook_id'=>'test-webhook'],'mercadopago'=>['access_token'=>'private-mp','webhook_secret'=>'private-signature','merchant_id'=>'12345','public_key'=>'public-mp'],'oxxo'=>['private_key'=>'private-oxxo','webhook_public_key'=>'test-rsa']};}
 private function setupBad(string $provider='paypal'):array{$o=$this->owner();$v=$this->venue($o);$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>$provider,'enabled'=>true,'sandbox'=>true,'credentials'=>$this->credentials($provider)]);$oldKey=random_bytes(32);$raw=(new Encrypter($oldKey,'AES-256-CBC'))->encryptString(json_encode($this->credentials($provider)));DB::table('gateway_accounts')->where('id',$g->id)->update(['credentials'=>$raw]);return [$o,$v,$g->fresh(),$raw,$oldKey];}
 private function booking(Venue $v,User $u){return app(BookingEngine::class)->reserve($v,$u->id,['date'=>now('America/Mexico_City')->addMonth()->startOfWeek()->addDays(2)->format('Y-m-d'),'start'=>14,'hours'=>8,'guests'=>20]);}
 public function test_owner_can_load_unreadable_accounts_without_secrets_or_mutation():void{[$o,$v,$g,$raw]=$this->setupBad();$r=$this->actingAs($o)->getJson('/api/owner/venues/'.$v->slug.'/gateways')->assertOk()->assertJsonPath('0.unreadable',true)->assertJsonPath('0.usable',false)->assertJsonPath('0.public_fields',[])->assertJsonMissingPath('0.credentials');$this->assertStringNotContainsString($raw,$r->getContent());$this->assertStringNotContainsString('test-private',$r->getContent());$this->assertSame($raw,DB::table('gateway_accounts')->where('id',$g->id)->value('credentials'));}
 public function test_save_requires_explicit_replacement_and_does_not_discard_ciphertext():void{[$o,$v,$g,$raw]=$this->setupBad();$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'credentials'=>$this->credentials()])->assertUnprocessable();$this->assertDatabaseCount('gateway_accounts',1);$this->assertSame($raw,DB::table('gateway_accounts')->where('id',$g->id)->value('credentials'));}
 public function test_incomplete_replacement_never_disables_or_replaces_old_account():void{[$o,$v,$g,$raw]=$this->setupBad();$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'replace'=>true,'credentials'=>['client_id'=>'new-client']])->assertUnprocessable();$this->assertTrue($g->fresh()->current);$this->assertTrue($g->fresh()->enabled);$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));}
 public function test_complete_replacement_creates_new_account_preserves_original_and_existing_order():void{[$o,$v,$g,$raw]=$this->setupBad();$b=$this->booking($v,User::factory()->create());$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','external_id'=>'OLDORDER','expires_at'=>now()->addMinutes(15)]);$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'replace'=>true,'credentials'=>$this->credentials()])->assertOk()->assertJsonPath('unreadable',false)->assertJsonPath('usable',true);$new=GatewayAccount::where('current',true)->first();$this->assertNotSame($g->id,$new->id);$this->assertFalse($g->fresh()->current);$this->assertFalse($g->fresh()->enabled);$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));$this->assertSame('test-private',$new->credentials['client_secret']);$this->assertSame($g->id,$a->fresh()->gateway_account_id);$this->assertStringEndsWith('/'.$new->id,$this->getJson('/api/owner/venues/'.$v->slug.'/gateways')->json('0.webhook_url'));}
 public function test_replacement_applies_to_mercado_pago_and_oxxo_too():void{foreach(['mercadopago','oxxo'] as $p){[$o,$v,$g,$raw]=$this->setupBad($p);$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/'.$p,['enabled'=>true,'sandbox'=>true,'replace'=>true,'credentials'=>$this->credentials($p)])->assertOk()->assertJsonPath('usable',true);$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));}}
 public function test_disabled_unreadable_account_keeps_original_ciphertext_without_dirty_check():void{[$o,$v,$g,$raw]=$this->setupBad();$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>false,'sandbox'=>true,'credentials'=>[]])->assertOk()->assertJsonPath('enabled',false)->assertJsonPath('unreadable',true);$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));$this->assertTrue($g->fresh()->current);}
 public function test_other_owner_cannot_recover_or_read_gateway_configuration():void{[$o,$v,$g,$raw]=$this->setupBad();$this->actingAs($this->owner())->getJson('/api/owner/venues/'.$v->slug.'/gateways')->assertForbidden();$this->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'replace'=>true,'credentials'=>$this->credentials()])->assertForbidden();$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));}
 public function test_previous_key_recovers_original_without_replacement():void{[$o,$v,$g,$raw,$key]=$this->setupBad();$current=app('encrypter');$recovery=new Encrypter($current->getKey(),'AES-256-CBC');$recovery->previousKeys([$key]);$this->app->instance('encrypter',$recovery);Crypt::swap($recovery);$this->actingAs($o)->getJson('/api/owner/venues/'.$v->slug.'/gateways')->assertOk()->assertJsonPath('0.unreadable',false)->assertJsonPath('0.public_fields.client_id','test-client');$this->assertSame($raw,$g->fresh()->getRawOriginal('credentials'));$this->assertDatabaseCount('gateway_accounts',1);}
 public function test_customer_does_not_see_unreadable_provider_and_start_does_not_create_order():void{[$o,$v,$g,$raw]=$this->setupBad();$u=User::factory()->create();$b=$this->booking($v,$u);Http::fake();$this->actingAs($u)->getJson('/api/bookings/'.$b->id.'/payment-options')->assertOk()->assertJsonCount(0,'providers');$this->postJson('/api/bookings/'.$b->id.'/checkout',['provider'=>'paypal','purpose'=>'deposit','policy_accepted'=>true])->assertUnprocessable();$this->assertDatabaseCount('checkout_attempts',0);Http::assertNothingSent();}
 public function test_existing_attempt_status_loads_with_warning_but_capture_never_issues_charge():void{[$o,$v,$g,$raw]=$this->setupBad();$u=User::factory()->create();$b=$this->booking($v,$u);$a=CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','external_id'=>'OLDORDER','expires_at'=>now()->addMinutes(15)]);Http::fake();$this->actingAs($u)->getJson('/api/checkout/'.$a->id)->assertOk()->assertJsonPath('sdk.client_id',null);$this->postJson('/api/checkout/'.$a->id.'/capture')->assertUnprocessable();Http::assertNothingSent();$this->assertSame(0,$b->payments()->count());}
 public function test_changing_valid_secret_creates_version_for_existing_orders():void{[$o,$v,$bad]=$this->setupBad();DB::table('gateway_accounts')->where('id',$bad->id)->delete();$g=GatewayAccount::create(['venue_id'=>$v->id,'provider'=>'paypal','current'=>true,'enabled'=>true,'sandbox'=>true,'credentials'=>$this->credentials()]);$b=$this->booking($v,User::factory()->create());CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>'paypal','amount'=>$b->deposit,'currency'=>'MXN','status'=>'pending','external_id'=>'OLDORDER','expires_at'=>now()->addMinutes(15)]);$this->actingAs($o)->putJson('/api/owner/venues/'.$v->slug.'/gateways/paypal',['enabled'=>true,'sandbox'=>true,'credentials'=>['client_secret'=>'new-secret']])->assertOk();$this->assertSame('test-private',$g->fresh()->credentials['client_secret']);$this->assertSame('new-secret',GatewayAccount::where('current',true)->first()->credentials['client_secret']);}
 public function test_key_status_reports_only_fingerprints_and_unreadable_count():void{[$o,$v,$g,$raw]=$this->setupBad();$fingerprint=substr(hash('sha256',app('encrypter')->getKey()),0,16);$this->artisan('security:key-status')->expectsOutput('clave_actual_huella: '.$fingerprint)->expectsOutput('pasarelas_actuales_ilegibles: 1')->expectsOutput('Solo se muestran huellas SHA-256, nunca las claves ni las credenciales.')->assertSuccessful();}

}
